// Layer names, colours and draw order per PDK (generated by scripts/gen-layer-stack.sh).
import sg13g2 from "../pdk/ihp-sg13g2.json";

export interface LayerInfo {
  key: number;
  name: string;
  layer: number;
  datatype: number;
  color: [number, number, number];
  /// Higher draws on top.
  order: number;
  /// Shown by default.
  visible: boolean;
  /// False for hollow layers (KLayout dither `I1`, e.g. boundaries): outline only.
  fill: boolean;
}

interface StackEntry {
  name: string;
  layer: number;
  datatype: number;
  fill: string;
  dither: string;
  order: number;
  visible: boolean;
}

const stacks: Record<string, { layers: StackEntry[] }> = { "ihp-sg13g2": sg13g2 };

export const layerKey = (layer: number, datatype: number) => layer * 65536 + datatype;

function hexColor(hex: string): [number, number, number] {
  const n = parseInt(hex.replace("#", ""), 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

/** A stable colour for layers the PDK table does not know. */
function fallbackColor(key: number): [number, number, number] {
  const h = ((key * 2654435761) >>> 0) / 2 ** 32;
  const f = (n: number) => {
    const k = (n + h * 12) % 12;
    return 0.6 - 0.35 * Math.max(-1, Math.min(k - 3, 9 - k, 1));
  };
  return [f(0), f(8), f(4)];
}

export function layerInfo(pdk: string, key: number): LayerInfo {
  const layer = Math.floor(key / 65536);
  const datatype = key % 65536;
  const entry = stacks[pdk]?.layers.find((l) => l.layer === layer && l.datatype === datatype);
  if (entry) {
    return {
      key,
      name: entry.name,
      layer,
      datatype,
      color: hexColor(entry.fill),
      order: entry.order,
      visible: entry.visible,
      fill: entry.dither !== "I1",
    };
  }
  return { key, name: `${layer}/${datatype}`, layer, datatype, color: fallbackColor(key), order: -1, visible: false, fill: true };
}

export const cssColor = ([r, g, b]: [number, number, number]) =>
  `rgb(${Math.round(r * 255)} ${Math.round(g * 255)} ${Math.round(b * 255)})`;
